import type { SourceInfo } from "../../agents/sessions/source-info.js";

export interface Skill {
  name: string;
  description: string;
  filePath: string;
  baseDir: string;
  /** Deterministic marker for the SKILL.md content rendered as <version>. */
  promptVersion?: string;
