      if (outcome.status !== "compacted") {
        throw new Error("Compaction cancelled");
      }

      this.emit({
        type: "compaction_end",
        reason: "manual",
        result: outcome.result,
        aborted: false,
        willRetry: false,
      });
      return outcome.result;
    } catch (error) {
      const message = error instanceof Error ? error.message : String(error);
      const aborted =
        message === "Compaction cancelled" ||
