## 在 createOpenClawCodingTools 内部（agent-tools.ts）

```typescript
// 第 549 行：构建时决定模式
const isMemoryFlushRun = options?.trigger === "memory";

// 如果 memory flush，校验必须提供写入路径
if (isMemoryFlushRun && !options?.memoryFlushWritePath) {
  throw new Error("memoryFlushWritePath required for memory-triggered tool runs");
}

// 接下来构建所有工具（正常构建，包括普通 write）
const tools = [
  ...buildReadTool(...),
  ...buildWriteTool(...),        // ← 普通 write 被构造出来了
  ...buildExecTool(...),
  ...buildBashTool(...),
  ...buildEditTool(...),
  ...
];

// 第 1079 行附近：内存冲刷时，替换工具列表
if (isMemoryFlushRun && memoryFlushWritePath) {
  const toolsForMemoryFlush: Tool[] = [];
  for (const tool of tools) {
    if (!MEMORY_FLUSH_ALLOWED_TOOL_NAMES.has(tool.name)) continue;    // 跳过非 read/write
    if (tool.name === "write") {
      toolsForMemoryFlush.push(
        wrapToolMemoryFlushAppendOnlyWrite(tool, {  // ← 替换为 wrapped 版本
          root: memoryFlushWriteRoot,
          relativePath: memoryFlushWritePath,       // "memory/active.md"
          containerWorkdir: sandbox?.containerWorkdir,
          sandbox: sandbox?.enabled ? { root, bridge } : undefined,
        })
      );
      continue;
    }
    toolsForMemoryFlush.push(tool);  // ← read 保留原样
  }
  return toolsForMemoryFlush;        // ← 只返回 read + wrapped write
}

return tools;  // ← 正常模式返回全部工具（普通 write 等）
```

