```rust
// bash.rs:1960-2040
fn sanitize_terminal_output(s: &str) -> String {
    // 1. ANSI 转义码擦除（手动逐字节扫描，不用 regex crate）
    //    处理 CSI（ESC [ ... final）、OSC（ESC ] ... BEL/ST）、两字节转义
    let cleaned = String::from_utf8_lossy(&stripped).into_owned();

    // 2. \r 进度条重建 —— 只保留每行最后一个 \r 之后的内容
    for (idx, line) in cleaned.split('\n').enumerate() {
        let line = line.trim_end_matches('\r');         // ← 同时清掉 \r\n 的尾部 \r
        if let Some(pos) = line.rfind('\r') {
            out.push_str(&line[pos + 1..]);              // ← 只取最后一段
        } else {
            out.push_str(line);
        }
    }
